import{_ as a,o as t,c as r,a4 as i}from"./chunks/framework.CzJ_HCFe.js";const p=JSON.parse('{"title":"Gold / Jewelry Source Profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/28-gold-jewelry-profile.md","filePath":"reference/28-gold-jewelry-profile.md","lastUpdated":1787887572000}'),o={name:"reference/28-gold-jewelry-profile.md"};function n(d,e,s,l,h,c){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="gold-jewelry-source-profile" tabindex="-1">Gold / Jewelry Source Profile <a class="header-anchor" href="#gold-jewelry-source-profile" aria-label="Permalink to &quot;Gold / Jewelry Source Profile&quot;">​</a></h1><h2 id="claim-and-authority" tabindex="-1">Claim and authority <a class="header-anchor" href="#claim-and-authority" aria-label="Permalink to &quot;Claim and authority&quot;">​</a></h2><p>The <code>gold</code> activity is linked to <code>muhurta.gold_jewelry.purchase</code>. Its authority is B. V. Raman&#39;s <em>Muhurtha</em>, Chapter X, &quot;Buying Jewelry,&quot; printed page 45 (PDF page 49 in the registered edition). Raman is a modern secondary authority, not scripture.</p><p>The passage is brief: Surya and Chandra should be well situated and aspected, and the usual unfavorable Tithis and Nakshatras should be avoided. The first condition remains a visible manual chart check. The second points back to general Panchanga-Suddhi rather than defining a jewelry-specific list.</p><h2 id="what-the-citation-does-not-support" tabindex="-1">What the citation does not support <a class="header-anchor" href="#what-the-citation-does-not-support" aria-label="Permalink to &quot;What the citation does not support&quot;">​</a></h2><p>The passage does not name a jewelry-specific weekday, Tithi, Nakshatra, Lagna, or Choghadiya. Consequently, the existing Labh-Choghadiya, Bhadra-Tithi, Friday/Thursday, and fixed-Lagna preferences remain explicitly classified as project heuristics. They do not inherit textual authority from this claim.</p><p>This negative boundary is part of the profile: attaching a relevant citation without delimiting its reach would make the evidence appear stronger than it is. Python, MCP, and the generated browser contract publish the same claim ID and manual check.</p>',7)])])}const f=a(o,[["render",n]]);export{p as __pageData,f as default};
